testbench_code:
`timescale 1ns/1ps
module tb_cdc_handshake;
    reg clk_src;
    reg rst_src_n;
    reg pulse_in_src;
    wire busy_src;

    reg clk_dst;
    reg rst_dst_n;
    wire pulse_out_dst;

    cdc_handshake dut (
        .clk_src(clk_src),
        .rst_src_n(rst_src_n),
        .pulse_in_src(pulse_in_src),
        .busy_src(busy_src),
        .clk_dst(clk_dst),
        .rst_dst_n(rst_dst_n),
        .pulse_out_dst(pulse_out_dst)
    );

    always #10 clk_src = ~clk_src;
    always #35 clk_dst = ~clk_dst;

    initial begin
        #20000;
        $display("FAIL: Simulation watchdog timeout (CDC handshake hang)");
        $fatal(1);
    end

    integer dst_pulse_count;
    always @(posedge clk_dst) begin
        if (rst_dst_n && pulse_out_dst) begin
            dst_pulse_count <= dst_pulse_count + 1;
        end
    end

    initial begin
        clk_src = 0;
        rst_src_n = 0;
        pulse_in_src = 0;
        clk_dst = 0;
        rst_dst_n = 0;
        dst_pulse_count = 0;
        #50;
        rst_src_n = 1;
        rst_dst_n = 1;
        #100;

        for (integer p = 0; p < 5; p = p + 1) begin
            @(posedge clk_src);
            pulse_in_src = 1;
            @(posedge clk_src);
            pulse_in_src = 0;

            while (busy_src) @(posedge clk_src);
            #100;
        end

        #200;
        if (dst_pulse_count !== 5) begin
            $display("FAIL: Expected exactly 5 destination pulses, got %0d", dst_pulse_count);
            $fatal(1);
        end

        $display("ALL_TESTS_PASSED");
        $finish;
    end
endmodule
